 [STAThread]static int Main(string[] args){Store.Root=args[0];Directory.CreateDirectory(Store.Root);Check(new Config().SkinShuffleMinutes==60&&new SkinShuffleSession().Minutes==60,"configuration and timer session default to sixty minutes");var custom=new Config{SkinShuffleMinutes=87};custom.Validate();Check(custom.SkinShuffleMinutes==87,"explicit custom intervals are preserved");
  Store.Save(new Config{LinkChatGPT=false,MusicEnabled=false,Walking=false,Gravity=false,AmbientActions=false,SleepSchedule=false,IdleSleep=false,HideFullscreen=false,LaunchChatGPTOnStart=false,LaunchMusicOnStart=false,NoticeSound=false,SkinShuffleEnabled=false,SkinShuffleOnStart=false,SkinShuffleJitter=false,SmoothTransitions=false,ReduceMotion=false,Bubbles=true});var app=new Application{ShutdownMode=ShutdownMode.OnLastWindowClose};var pet=new PetWindow(true);bool passed=false;
