    pet.Settings.SkinShuffleActions=new[]{"pat","stretch"};Set(pet,"lastSkinAction","pat");pet.SelectSkin(Other(pet));Check(Equals(F(pet,"skinShowcaseAction"),"stretch"),"manual selection honors the shared last-action history");Call(pet,"ApplyAutomaticSkin",Other(pet),Now(pet));Check(Equals(F(pet,"skinShowcaseAction"),"pat"),"random selection continues the same action pool and repeat protection");Call(pet,"StopSkinVisual");
    pet.Settings.SkinShuffleMusicMode="stand-first";Set(pet,"state","music-quiet");Set(pet,"drawnMusicState","music-quiet");pet.Settings.MusicEnabled=true;pet.Music.Current=new MusicState{Connected=true,Playing=true,Title="Synthetic song",Id="123",HasPosition=false};Call(pet,"ChooseMusicReaction",Now(pet)-10,true);Call(pet,"ChooseMusicReaction",Now(pet),true);var reaction=F(pet,"musicReactionPlanner");var entered=F(reaction,"enteredAt");pet.Settings.SkinShuffleActions=new[]{"groom"};Clear(pet);pet.SelectSkin(Other(pet));At(pet,300);Check(pet.CurrentAction=="music-rise","manual seated change begins with the existing rise");At(pet,720+700);Check(pet.CurrentAction=="groom","manual seated change plays the checked grooming action");At(pet,720+2100+300);Check(pet.CurrentAction=="music-sit","manual seated change returns through the existing sit");At(pet,3600);Check(pet.CurrentAction=="music-quiet"&&!Running(pet)&&ReferenceEquals(reaction,F(pet,"musicReactionPlanner"))&&Equals(entered,F(reaction,"enteredAt"))&&(double)F(pet,"stateAt")==phase,"manual seated change retains music session and timeline");
    pet.Settings.SmoothTransitions=true;Clear(pet);pet.SelectSkin(Other(pet));Check(!(bool)F(pet,"skinVisualRunning")&&Running(pet)&&pet.CurrentAction=="music-rise","manual seated change raises the old skin before fading");At(pet,720);await Task.Delay(370);Check(Running(pet)&&pet.CurrentAction=="groom","manual fade follows the rise without restarting the sequence");Call(pet,"StopSkinVisual");pet.Settings.SmoothTransitions=false;
    Set(pet,"state","idle");pet.Settings.MusicEnabled=false;Call(pet,"OpenMenu");var menu=(ContextMenu)F(pet,"toolbarMenu");await Task.Delay(50);Capture(menu,"context-menu.png");var skins=menu.Items.OfType<MenuItem>().Single(m=>Convert.ToString(m.Header)=="换一套衣服");var outfit=skins.Items.OfType<MenuItem>().First(m=>!m.IsChecked&&Convert.ToString(m.Header)!="今天固定这套"&&Convert.ToString(m.Header)!="恢复随机换装并重新计时");outfit.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(!menu.IsOpen&&Running(pet),"actual outfit menu closes before direct shared feedback starts");Call(pet,"StopSkinVisual");
   }
   pet.Settings.SkinShuffleActions=new string[0];Clear(pet);pet.SelectSkin(Other(pet));Check(!Running(pet)&&F(pet,"interaction")==null&&SkinChangeMessages.Contains(((TextBlock)F(pet,"bubbleText")).Text),"empty manual action selection gives only a varied bubble");double start=(double)F(pet,"stateAt");var image=((Image)F(pet,"sprite")).Source;Clear(pet);pet.SelectSkin(pet.Settings.Skin);Check(((Border)F(pet,"bubble")).Visibility!=Visibility.Visible&&ReferenceEquals(image,((Image)F(pet,"sprite")).Source)&&(double)F(pet,"stateAt")==start,"same-skin selection does not replay an action or bubble");
   pet.Settings.SkinShuffleActions=new[]{"stretch"};pet.Settings.LinkChatGPT=true;pet.Link.Current.Connected=true;pet.Link.Current.State="running";pet.Link.Current.At=DateTime.UtcNow;Clear(pet);pet.SelectSkin(Other(pet));Check(!Running(pet)&&F(pet,"interaction")==null&&((Border)F(pet,"bubble")).Visibility!=Visibility.Visible,"manual outfit change respects active GPT priority");pet.Settings.LinkChatGPT=false;
   pet.Settings.ReduceMotion=true;Call(pet,"ApplyInputOptions");Clear(pet);pet.SelectSkin(Other(pet));Check(!Running(pet)&&SkinChangeMessages.Contains(((TextBlock)F(pet,"bubbleText")).Text),"reduced-motion manual change keeps static shared feedback");pet.Settings.ReduceMotion=false;Call(pet,"ApplyInputOptions");
   pet.CancelSkinShuffleRequest();var context=(ContextMenu)Call(pet,"BuildPetMenu");var request=context.Items.OfType<MenuItem>().Single(m=>Convert.ToString(m.Header)=="立即随机换装");Check(request.IsEnabled&&context.Items.IndexOf(request)==0,"pet context menu exposes a top-level randomize action");request.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(pet.SkinShuffleRequested&&!pet.Settings.SkinShuffleEnabled,"context menu queues a one-shot while automatic mode is off");context=(ContextMenu)Call(pet,"BuildPetMenu");Check(!context.Items.OfType<MenuItem>().Single(m=>Convert.ToString(m.Header)=="立即随机换装").IsEnabled,"queued context action cannot accumulate requests");pet.CancelSkinShuffleRequest();
   using(var tray=(System.Windows.Forms.ContextMenuStrip)Call(pet,"BuildTrayMenu")){var item=tray.Items.Cast<System.Windows.Forms.ToolStripItem>().Single(i=>i.Text=="立即随机换装");Check(item.Enabled,"tray context menu also exposes randomization");item.PerformClick();await Task.Delay(50);Check(pet.SkinShuffleRequested,"tray action dispatches into the same one-shot queue");}pet.CancelSkinShuffleRequest();
   pet.Settings.SkinShufflePool=new[]{pet.Settings.Skin};context=(ContextMenu)Call(pet,"BuildPetMenu");Check(!context.Items.OfType<MenuItem>().Single(m=>Convert.ToString(m.Header)=="立即随机换装").IsEnabled,"no alternative outfit disables the context action");pet.Settings.SkinShufflePool=SkinShuffleRules.Defaults.ToArray();
   Check(pet.Width==width&&pet.Height==height&&((DispatcherTimer)F(pet,"poll")).Interval==poll&&((DispatcherTimer)F(pet,"musicTimer")).Interval==musicPoll,"manual changes and menu requests preserve bounds and provider polling");pet.OpenSettings();var window=(SettingsWindow)F(pet,"settingsWindow");window.NavigateCategory("外观与互动","");((Expander)F(window,"skinShuffleSection")).IsExpanded=true;window.UpdateLayout();Capture((FrameworkElement)window.Content,"settings.png");window.Close();
   passed=true;
  }catch(Exception e){Store.Atomic("error.json",new{error=e.ToString(),checks});}finally{foreach(var w in app.Windows.Cast<Window>().Where(w=>w!=pet).ToArray())w.Close();pet.Close();}};app.Run(pet);Store.Atomic("result.json",new{passed,checks,names});return passed?0:1;
